import Papa from 'papaparse';
import { FlowItem, MerchantRecord } from '../types';
import { computeCategoryStatsMap, evaluateMerchantRisk } from './stats';

function parseJsonSafe(val: any): FlowItem[] {
  if (!val) return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') {
    const trimmed = val.trim();
    if (!trimmed || trimmed === '[]' || trimmed === 'null') return [];
    try {
      const parsed = JSON.parse(trimmed);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      // Handle escaped or double-quoted JSON strings commonly generated by Excel
      try {
        const cleaned = trimmed.replace(/^["']|["']$/g, '').replace(/""/g, '"');
        const parsed = JSON.parse(cleaned);
        return Array.isArray(parsed) ? parsed : [];
      } catch (err) {
        console.warn('Could not parse flow JSON:', val, err);
        return [];
      }
    }
  }
  return [];
}

/**
 * Flexible column accessor that searches row for any of the candidate keys
 */
function getField(row: Record<string, any>, candidates: string[]): any {
  for (const c of candidates) {
    if (row[c] !== undefined && row[c] !== null && row[c] !== '') {
      return row[c];
    }
  }
  // Try case-insensitive fuzzy match across all row keys
  const keys = Object.keys(row);
  for (const c of candidates) {
    const normalizedTarget = c.toLowerCase().replace(/[^a-z0-9]/g, '');
    const matchedKey = keys.find(k => k.toLowerCase().replace(/[^a-z0-9]/g, '') === normalizedTarget);
    if (matchedKey && row[matchedKey] !== undefined && row[matchedKey] !== null && row[matchedKey] !== '') {
      return row[matchedKey];
    }
  }
  return undefined;
}

export function processParsedRows(rows: any[]): MerchantRecord[] {
  const preliminary: Omit<MerchantRecord, 'riskScore' | 'riskLevel' | 'riskFactors'>[] = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    if (!row || typeof row !== 'object') continue;

    // Support string, number, or alternate key names for merchant ID
    const rawId = getField(row, ['merchant_id', 'merchantid', 'merchant', 'id', 'mch_id', 'account_id']);
    if (rawId === undefined || rawId === null) continue;
    const merchant_id = String(rawId).trim();
    if (!merchant_id) continue;

    const declared_category = String(
      getField(row, ['declared_category', 'category', 'mcc_category', 'business_category']) || 'Uncategorized'
    ).trim();

    const monthly_volume_inr = Number(
      getField(row, ['monthly_volume_inr', 'monthly_volume', 'volume_inr', 'volume', 'amount'])
    ) || 0;

    const monthly_txn_count = Number(
      getField(row, ['monthly_txn_count', 'monthly_txns', 'txn_count', 'txns', 'count', 'transactions'])
    ) || 0;

    const avg_txn_value_inr = Number(
      getField(row, ['avg_txn_value_inr', 'avg_txn_value', 'avg_ticket', 'avg_amount'])
    ) || (monthly_txn_count > 0 ? monthly_volume_inr / monthly_txn_count : 0);

    const off_hours_ratio = Number(
      getField(row, ['off_hours_ratio', 'off_hours', 'off_hours_pct'])
    ) || 0;

    const round_amount_ratio = Number(
      getField(row, ['round_amount_ratio', 'round_amount', 'round_amount_pct'])
    ) || 0;

    const payout_velocity_hrs = Number(
      getField(row, ['payout_velocity_hrs', 'payout_velocity', 'payout_hrs', 'settlement_velocity'])
    ) || 24;

    const unique_payer_ratio = Number(
      getField(row, ['unique_payer_ratio', 'unique_payer', 'unique_payers'])
    ) || 0.6;

    const high_val_txn_ratio = Number(
      getField(row, ['high_val_txn_ratio', 'high_val_ratio', 'high_value_ratio'])
    ) || 0.05;

    const dispute_rate_pct = Number(
      getField(row, ['dispute_rate_pct', 'dispute_rate', 'dispute_pct', 'chargeback_rate'])
    ) || 0;

    const is_gambling_front = Number(
      getField(row, ['is_gambling_front', 'gambling_front', 'is_fraud', 'label'])
    ) || 0;

    const payer_cluster_ids = String(
      getField(row, ['payer_cluster_ids', 'payer_clusters']) || ''
    );

    const payout_destination_ids = String(
      getField(row, ['payout_destination_ids', 'payout_destinations']) || ''
    );

    const network_data_status = String(
      getField(row, ['network_data_status', 'status']) || 'synthetic demo flows'
    );

    // Parse flow JSONs
    let payer_flows_json = parseJsonSafe(getField(row, ['payer_flows_json', 'payer_flows', 'payer_flow']));
    let payout_flows_json = parseJsonSafe(getField(row, ['payout_flows_json', 'payout_flows', 'payout_flow']));

    // Fallback: If custom CSV doesn't have flow JSONs, synthesize realistic demo network counterparties
    if (payer_flows_json.length === 0 && monthly_volume_inr > 0) {
      const catCode = declared_category.slice(0, 3).toUpperCase().replace(/[^A-Z]/g, 'GEN');
      payer_flows_json = [
        {
          counterparty_id: `PAYPOOL_${catCode}_01`,
          direction: 'inflow_to_merchant',
          transaction_count: Math.round(monthly_txn_count * 0.65),
          flow_volume_inr: Math.round(monthly_volume_inr * 0.65 * 100) / 100,
        },
        {
          counterparty_id: `PAYPOOL_UNIQUE_${merchant_id}`,
          direction: 'inflow_to_merchant',
          transaction_count: Math.round(monthly_txn_count * 0.35),
          flow_volume_inr: Math.round(monthly_volume_inr * 0.35 * 100) / 100,
        },
      ];
    }

    if (payout_flows_json.length === 0 && monthly_volume_inr > 0) {
      payout_flows_json = [
        {
          counterparty_id: `PAYOUT_DEST_${merchant_id}`,
          direction: 'outflow_from_merchant',
          transaction_count: monthly_txn_count,
          flow_volume_inr: monthly_volume_inr,
        },
      ];
    }

    preliminary.push({
      merchant_id,
      declared_category,
      monthly_volume_inr,
      monthly_txn_count,
      avg_txn_value_inr,
      off_hours_ratio,
      round_amount_ratio,
      payout_velocity_hrs,
      unique_payer_ratio,
      high_val_txn_ratio,
      dispute_rate_pct,
      is_gambling_front,
      payer_cluster_ids,
      payer_flows_json,
      payout_destination_ids,
      payout_flows_json,
      network_data_status,
    });
  }

  if (preliminary.length === 0) {
    return [];
  }

  // Calculate peer medians first so risk calculation can measure relative category deviation
  const dummyMerchants: MerchantRecord[] = preliminary.map(p => ({
    ...p,
    riskScore: 0,
    riskLevel: 'Low',
    riskFactors: [],
  }));

  const categoryMap = computeCategoryStatsMap(dummyMerchants);

  // Evaluate risk score for each merchant (strictly without using is_gambling_front)
  return preliminary.map(p => {
    const catStats = categoryMap.get(p.declared_category);
    const risk = evaluateMerchantRisk(p, catStats);
    return {
      ...p,
      riskScore: risk.riskScore,
      riskLevel: risk.riskLevel,
      riskFactors: risk.riskFactors,
    };
  });
}

export async function loadDefaultDataset(): Promise<MerchantRecord[]> {
  const url = '/payu_merchant_fraud_dataset_enhanced.csv';
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to load default dataset from ${url} (HTTP ${response.status})`);
  }
  const text = await response.text();
  return parseCsvString(text);
}

export function parseCsvString(csvText: string): Promise<MerchantRecord[]> {
  return new Promise((resolve, reject) => {
    Papa.parse(csvText, {
      header: true,
      dynamicTyping: true,
      skipEmptyLines: 'greedy',
      transformHeader: (header: string) => {
        // Strip BOM, trim, replace spaces/dashes with underscores and lowercase
        return header
          .replace(/^\uFEFF/, '')
          .trim()
          .toLowerCase()
          .replace(/[\s\-]+/g, '_');
      },
      complete: (results) => {
        try {
          if (!results.data || results.data.length === 0) {
            reject(new Error('CSV file appears to be empty or has no rows.'));
            return;
          }
          const records = processParsedRows(results.data);
          if (records.length === 0) {
            reject(
              new Error(
                'No valid merchant rows found. Ensure the CSV contains a merchant identifier column (e.g. "merchant_id" or "id").'
              )
            );
            return;
          }
          resolve(records);
        } catch (err: any) {
          reject(new Error(`Error parsing dataset: ${err.message}`));
        }
      },
      error: (error: any) => {
        reject(new Error(`PapaParse Error: ${error.message}`));
      },
    });
  });
}

export function parseCsvFile(file: File): Promise<MerchantRecord[]> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text || text.trim() === '') {
        reject(new Error(`File "${file.name}" is completely empty.`));
        return;
      }
      parseCsvString(text).then(resolve).catch(reject);
    };
    reader.onerror = () => {
      reject(new Error(`Failed to read file "${file.name}" from disk.`));
    };
    reader.readAsText(file);
  });
}
